div.script:
(function () {
    var nextIndex = 0;

    function addRow(data) {
        var template = document.querySelector(
            '#education_row_template .education-row'
        );
        if (!template) return;
        var row = template.cloneNode(true);
        var idx = nextIndex++;
        var fields = row.querySelectorAll('[data-field]');
        for (var i = 0; i < fields.length; i++) {
            var f = fields[i];
            var name = 'education_' + f.getAttribute('data-field') + '_' + idx;
            f.setAttribute('name', name);
        }
        if (data.level) row.querySelector("[data-field='level']").value = data.level;
        if (data.program) row.querySelector("[data-field='program']").value = data.program;
        if (data.major) row.querySelector("[data-field='major']").value = data.major;
        if (data.institution) row.querySelector("[data-field='institution']").value = data.institution;
        if (data.country_id) row.querySelector("[data-field='country_id']").value = data.country_id;
        if (data.graduation_date) row.querySelector("[data-field='graduation_date']").value = data.graduation_date;
        document.getElementById('education_rows_container').appendChild(row);
    }

    function reindexRows() {
        var container = document.getElementById('education_rows_container');
        var rows = container.querySelectorAll('.education-row');
        for (var r = 0; r < rows.length; r++) {
            var fields = rows[r].querySelectorAll('[data-field]');
            for (var i = 0; i < fields.length; i++) {
                var f = fields[i];
                f.setAttribute('name', 'education_' + f.getAttribute('data-field') + '_' + r);
            }
        }
        nextIndex = rows.length;
    }

    document.addEventListener('click', function (ev) {
        var btn = ev.target.closest('#education_add_btn');
        if (btn) {
            ev.preventDefault();
            addRow({});
            return;
        }
        var removeBtn = ev.target.closest('.education-remove-btn');
        if (removeBtn) {
            ev.preventDefault();
            removeBtn.closest('.education-row').remove();
            reindexRows();
        }
    });

    // Pre-fill on load
    var prefillEl = document.getElementById('education_prefill_data');
    if (prefillEl && prefillEl.value) {
        try {
            var data = JSON.parse(prefillEl.value);
            for (var i = 0; i < data.length; i++) {
                addRow(data[i]);
            }
        } catch (e) {}
    }
})();
